package com.portfolio.assetory.purchase.dto.response;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;import com.portfolio.assetory.access.domain.ProductAccess;
public record PurchaseListResponse(List<Product> products,int page,int totalPages){public static PurchaseListResponse from(org.springframework.data.domain.Page<ProductAccess> page,java.util.Map<Long,String> thumbnails){return new PurchaseListResponse(page.getContent().stream().map(a->{var i=a.getOrderItem();var p=i.getProduct();return new Product(i.getId(),p.getId(),i.getProductName(),thumbnails.get(p.getId()),p.getSeller().getNickname(),i.getUnitPrice(),a.getGrantedAt());}).toList(),page.getNumber(),page.getTotalPages());}public record Product(Long orderItemId,Long productId,String name,String thumbnailUrl,String sellerNickname,BigDecimal purchasedPrice,LocalDateTime purchasedAt){}}
